-- Stable slugs, polymorphic targets, tenant references and scoped label printing.
select no_plan();
select tests.create_range_fixture();
select throws_ok($test$insert into public.qr_codes(organisation_id,slug,target_type,target_id) values ('10000000-0000-0000-0000-000000000001','foreign-show','show','93000000-0000-0000-0000-000000000002')$test$,'23514',null,'QR cannot target foreign show');
select throws_ok($test$insert into public.qr_codes(organisation_id,slug,target_type,target_id) values ('10000000-0000-0000-0000-000000000001','foreign-collection','collection','92000000-0000-0000-0000-000000000002')$test$,'23514',null,'QR cannot target foreign collection');
select throws_ok($test$insert into public.qr_codes(organisation_id,slug,target_type,target_id) values ('10000000-0000-0000-0000-000000000001','draft-target','product','60000000-0000-0000-0000-000000000002')$test$,'23514',null,'QR cannot target draft product');
select throws_ok($test$insert into public.qr_codes(organisation_id,slug,target_type,target_id) values ('10000000-0000-0000-0000-000000000001','wrong-pack','pack','60000000-0000-0000-0000-000000000001')$test$,'23514',null,'pack target validates kind');
select throws_ok($test$insert into public.qr_codes(organisation_id,slug,target_type,target_id) values ('10000000-0000-0000-0000-000000000001','unknown-target','product','60000000-0000-0000-0000-000000000099')$test$,'23514',null,'unknown target is rejected');
select throws_ok($test$insert into public.qr_codes(organisation_id,store_id,slug,target_type) values ('10000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000002','foreign-store','store')$test$,'23503',null,'QR store must belong to retailer');
select throws_ok($test$insert into public.qr_codes(organisation_id,campaign_id,slug,target_type) values ('10000000-0000-0000-0000-000000000001','94000000-0000-0000-0000-000000000002','foreign-campaign','planner')$test$,'23503',null,'QR campaign must belong to retailer');
select throws_ok($test$insert into public.label_batches(organisation_id,qr_code_ids,size) values ('10000000-0000-0000-0000-000000000001',array['95000000-0000-0000-0000-000000000002'::uuid],'a6_card')$test$,'23514',null,'labels cannot include foreign QR code');
select throws_ok($test$insert into public.label_batches(organisation_id,qr_code_ids,size) values ('10000000-0000-0000-0000-000000000001',array[null::uuid],'a6_card')$test$,'23514',null,'labels cannot include null QR UUID');
select throws_ok($test$insert into public.label_batches(organisation_id,qr_code_ids,size,pdf_media_id) values ('10000000-0000-0000-0000-000000000001',array['95000000-0000-0000-0000-000000000001'::uuid],'a6_card','30000000-0000-0000-0000-000000000004')$test$,'23514',null,'label media cannot cross tenants');
select throws_ok($test$update public.qr_codes set slug = 'reused'$test$,'23514',null,'QR slug is immutable');
select throws_ok('delete from public.qr_codes','23514',null,'QR codes cannot be deleted even by backend');
update public.qr_codes set status = 'archived' where slug = 'fixture-1';
select throws_ok($test$insert into public.qr_codes(organisation_id,slug,target_type) values ('10000000-0000-0000-0000-000000000001','fixture-1','planner')$test$,'23505',null,'archived slug cannot be reused');
update public.memberships set store_ids = array['90000000-0000-0000-0000-000000000001'::uuid] where profile_id = tests.get_supabase_uid('organisation_manager');
reset role;
select tests.act_as('organisation_manager');
select lives_ok($test$insert into public.label_batches(organisation_id,qr_code_ids,size) values ('10000000-0000-0000-0000-000000000001',array['95000000-0000-0000-0000-000000000001'::uuid],'a6_card')$test$,'store-restricted manager can print assigned labels');
select lives_ok($test$update public.qr_codes set status = 'live' where slug = 'fixture-1'$test$,'manager manages assigned store code');
select is(tests.import_affected_rows($test$update public.qr_codes set status = 'paused' where slug = 'fixture-2'$test$),0::bigint,'manager cannot manage another store');
reset role;
select tests.act_as('organisation_owner');
select lives_ok($test$insert into public.qr_codes(organisation_id,store_id,slug,target_type,target_id) values ('10000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001','catalogue-product','product','60000000-0000-0000-0000-000000000001')$test$,'retailer can target published catalogue product');
select lives_ok($test$insert into public.qr_codes(organisation_id,store_id,slug,target_type,target_id) values ('10000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001','catalogue-pack','pack','60000000-0000-0000-0000-000000000003')$test$,'retailer can target published catalogue pack');
reset role;
select tests.act_as_public();
select is(public.resolve_qr('catalogue-product')->>'target_type','product','visible product resolves');
select is(public.resolve_qr('catalogue-pack')->>'target_type','store','pack outside store range falls back');
reset role;
select tests.act_as('retailer_staff');
select lives_ok($test$insert into public.label_batches(organisation_id,qr_code_ids,size) values ('10000000-0000-0000-0000-000000000001',array['95000000-0000-0000-0000-000000000001'::uuid],'a6_card')$test$,'store staff can print labels for assigned store');
select is(tests.import_affected_rows($test$update public.qr_codes set status = 'paused' where slug = 'fixture-1'$test$),0::bigint,'store staff cannot manage QR codes');
select throws_ok($test$select public.record_stock('90000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001',1,'manual')$test$,'42501',null,'store staff cannot manage stock');
select finish();
